{"content": "1|import path from "node:path";
2|
3|import { assert } from "@std/assert";
4|import { parseArgs } from "@std/cli/parse-args";
5|
6|import { makeFinalResult, parse } from "./impl-by-llms/mod.ts";
7|import { FinalResult, PropertyInfos, Structure } from "./types.ts";
8|
9|const args = parseArgs(Deno.args, {
10|  string: ["crate-path"],
11|});
12|
13|if (!args["crate-path"]) throw new Error("Missing `--crate-path`");
14|
15|const headerPath = path.join(
16|  args["crate-path"],
17|  "vendor",
18|  "openfx",
19|  "openfx-cpp",
20|  "include",
21|  "openfx",
22|  "ofxPropsMetadata.h",
23|);
24|
25|const headerCode = await Deno.readTextFile(headerPath);
26|const result = parse(headerCode);
27|const finalResult = makeFinalResult(result);
28|
29|Deno.test("parsing", (t) => {
30|  t.step("structure", () => {
31|    Structure.parse(result.structure);
32|  });
33|
34|  t.step("propertyInfos", () => {
35|    assert(Object.keys(result.propertyInfos.propEnumValues).length > 0);
36|    assert(Object.keys(result.propertyInfos.propTypeArrays).length > 0);
37|    assert(Object.keys(result.propertyInfos.propDefsArray).length > 0);
38|    PropertyInfos.parse(result.propertyInfos);
39|  });
40|});
41|
42|Deno.test("finalResult", (_t) => {
43|  assert(Object.keys(finalResult.propertyInfos).length > 0);
44|  FinalResult.parse(finalResult);
45|});
