export function makeFinalResult(result: Result): FinalResult {
  const { propEnumValues, propTypeArrays, propDefsArray } = result.propertyInfos;
  const propertyInfos: FinalResult["propertyInfos"] = {};
  for (const [name, defs] of Object.entries(propDefsArray)) {
    const def = defs[0];
    if (def === undefined) throw new Error(`no PropDef entries for "${name}"`);
    const types = propTypeArrays[`${name}_types`];
    if (types === undefined) throw new Error(`missing PropType array for "${name}"`);
    const primary = [...types][0];
    if (primary === undefined) throw new Error(`empty PropType set for "${name}"`);
    propertyInfos[name] = {
      type: primary === "Enum"
        ? { Enum: propEnumValues[name] ?? new Set<string>() }
        : primary,
      dimension: def.dimension,
    };
  }
  return { propertyInfos };
}
