function parseCppString(image: string): string {
  // Strict: the header's string literals are simple quoted names without escapes.
  const inner = image.slice(1, -1);
  if (image.length < 2 || image[0] !== '"' || image[image.length - 1] !== '"' || inner.includes('"') || inner.includes("\\")) {
    throw new Error(`unsupported string literal: ${image}`);
  }
  return inner;
}

function toInt(image: string): number {
  return Number(image); // NumberLiteral guarantees digits only
}
