export function parse(headerCode: string): Result {
  const lexing = lexer.tokenize(headerCode);
  if (lexing.errors.length > 0) {
    throw new Error(`Failed to lex ofxPropsMetadata.h:\n${lexing.errors.map((e) => e.message).join("\n")}`);
  }
  const parser = new OfxPropsMetadataParser();
  parser.input = lexing.tokens;
  parser.headerFile();
  if (parser.errors.length > 0) {
    throw new Error(`Failed to parse ofxPropsMetadata.h:\n${parser.errors.map((e) => e.message).join("\n")}`);
  }
  return {
    structure: [
      "pragmaOnce",
      "include[]",
      { type: "namespace:openfx", inner: parser.openfxInner } as ... 
    ],
    propertyInfos: {...},
  };
}
