```ts
import { CstParser, createToken, EOF, Lexer } from "chevrotain";
import type { FinalResult, PropType, Result, Structure } from "../types.ts";

/**
 * Parser for `ofxPropsMetadata.h`. See ./INSTRUCTIONS.md.
 *
 * The grammar mirrors the `Structure` schema in ../types.ts one-to-one: every
 * element of the expected structure corresponds to exactly one parser rule,
 * and the rules are sequenced exactly as the structure tuple prescribes.
 * Anything the header adds, removes, or reorders fails the parse.
 */

// ---------------------------------------------------------------------------
// Tokens
// ---------------------------------------------------------------------------

// -- skipped by the lexer ----------------------------------------------------

const WhiteSpace = createToken({ name: "WhiteSpace", pattern: /\s+/, group: Lexer.SKIPPED });
const LineComment = createToken({ name: "LineComment", pattern: /\/\/[^\n\r]*/, group: Lexer.SKIPPED });
const BlockComment = createToken({ name: "BlockComment", pattern: /\/\*[\s\S]*?\*\//, group: Lexer.SKIPPED });

// -- token categories --------------------------------------------------------
// Categories let the grammar consume "any token except X" inside regions whose
// exact contents do not contribute to the result (struct bodies, template
// parameter lists, static_assert expressions).

const AnyExceptBrace = createToken({ name: "AnyExceptBrace", pattern: Lexer.NA });
const AnyExceptParenOrSemicolon = createToken({ name: "AnyExceptParenOrSemicolon", pattern: Lexer.NA });
const AnyExceptAngleOrComma = createToken({ name: "AnyExceptAngleOrComma", pattern: Lexer.NA });

const anySoup = [AnyExceptBrace, AnyExceptParenOrSemicolon, AnyExceptAngleOrComma];

// -- preprocessor ------------------------------------------------------------

// `#define ...` including backslash-newline continuations.
const DefineDirective = createToken({ name: "DefineDirective", pattern: /#define[^\n\r]*(?:\\[^\n\r]*\n[^\n\r]*)*/ });
```

