        "OfxFieldLower",
        "OfxFieldUpper",
        "OfxFieldBoth",
        "OfxFieldSingle",
        "OfxFieldDoubled",
      ],
    },
    dimension: 1,
  }],
  ["bool prop", finalResult.propertyInfos["OfxImageClipPropConnected"], {
    type: "Bool",
    dimension: 1,
  }],
  ["multi-type prop", finalResult.propertyInfos["OfxParamPropDefault"], {
    type: "Int",
    dimension: 0,
  }],
  ["variable-dim prop", finalResult.propertyInfos["OfxImageEffectPropRenderWindow"], {
    type: "Int",
    dimension: 4,
  }],
  ["k-prefixed prop", finalResult.propertyInfos["kOfxPropKeySym"], {
    type: "Int",
    dimension: 1,
  }],
];

